	@Test
	void interruptedResetRetainsFormatAcrossAnotherInterruption() throws Exception {
		int version = 7;
		createGeneration(version);
		LmdbStoreFormat format = LmdbStoreFormat.fromProperties(readProperties(), config());
		Path marker = directory.resolve(LmdbInitialRunImport.markerFileName(format));
		Files.createFile(marker);
		byte[] metadata = Files.readAllBytes(directory.resolve(StoreProperties.FILE_NAME));
		byte[] compatibility = Files.readAllBytes(directory.resolve(LmdbStore.CORE_LITERAL_REFERENCE_MARKER_FILE));
		assertThat(LmdbInitialRunImport.resetInterruptedImport(directory, format)).isTrue();
		assertThat(marker).exists();
		assertThat(Files.readAllBytes(directory.resolve(StoreProperties.FILE_NAME))).isEqualTo(metadata);
		assertThat(Files.readAllBytes(directory.resolve(LmdbStore.CORE_LITERAL_REFERENCE_MARKER_FILE)))
				.isEqualTo(compatibility);
		// A second crash can happen after creating data.mdb, before its first native format fence commits.
		Files.createDirectories(directory.resolve("values"));
		Files.createFile(directory.resolve("values/data.mdb"));
		LmdbStore reopened = new LmdbStore(directory.toFile(), config());
		reopened.init();
		try {
			assertThat(reopened.getFormat().getVersion()).isEqualTo(version);
			assertThat(marker).doesNotExist();
			try (NotifyingSailConnection connection = reopened.getConnection()) {
				assertThat(connection.size()).isZero();
			}
		} finally {
			reopened.shutDown();
		}
		assertThat(readProperties().getVersion()).isEqualTo(Integer.toString(version));
		assertThat(LmdbCompatibilityFixtures.nativeGet(directory, "gc_meta", new byte[] { 3 }))
				.containsExactly((byte) version);
	}

