	private void completePreparedGeneration(int version) throws Exception {
		createGeneration(version);
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		store.init();
		try (NotifyingSailConnection connection = store.getConnection()) {
			var values = SimpleValueFactory.getInstance();
			connection.begin();
			// Prepared admission requires the authoritative namespace snapshot, published by a real mutation.
			connection.setNamespace("prepared", "urn:prepared:");
			connection.addStatement(values.createIRI("urn:prepared:", "branch/subject"),
					values.createIRI("urn:prepared:predicate"), values.createLiteral("completed generation"));
			connection.commit();
		} finally {
			store.shutDown();
		}
	}

	private void createGeneration(int version) throws Exception {
		StoreProperties properties = new StoreProperties(directory.toFile()).setVersion(Integer.toString(version))
				.setTripleIndexes("spoc,posc")
				.setTripleTermIndexes("spoc,cspo");
		if (version != 2) {
			properties.setInlineLiterals(true)
					.setLiteralReferenceEncoding(StoreProperties.LITERAL_REFERENCE_ENCODING_CORE_V1)
					.setCanonicalLanguageTags(StoreProperties.CANONICAL_LANGUAGE_TAGS_LOWERCASE_V1)
					.setDateTimeIdEncoding(StoreProperties.DATE_TIME_ID_ENCODING_ZERO_FRACTION_V1);
			LmdbStore.writeCoreLiteralReferenceMarker(directory);
		}
		LmdbSailStore store = new LmdbSailStore(directory.toFile(), properties, config(), false);
		try {
			properties.save();
		} finally {
			store.close();
		}
	}

	private StoreProperties readProperties() {
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertThat(properties.load()).isTrue();
		return properties;
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setTripleTermIndexes("spoc,cspo")
				.setSketchEstimatorEnabled(false);
	}
